import type { IClock } from '../types/interfaces.js'
import { SystemClock } from '../types/interfaces.js'

/**
 * Base class for all domain events. Events are immutable facts: once
 * constructed they are frozen and carry when/what/who metadata.
 */
export abstract class DomainEvent {
  readonly eventId: string
  readonly occurredAt: Date

  protected constructor(
    readonly eventName: string,
    readonly aggregateId: string,
    clock: IClock = new SystemClock()
  ) {
    this.eventId = crypto.randomUUID()
    this.occurredAt = clock.now()
  }
}

/**
 * Base class for value objects: immutable, compared by structural equality.
 * Props are frozen at construction; subclasses expose typed accessors.
 */
export abstract class ValueObject<T extends Record<string, unknown>> {
  protected readonly props: Readonly<T>

  protected constructor(props: T) {
    this.props = Object.freeze({ ...props })
  }

  equals(other?: ValueObject<T>): boolean {
    if (other === null || other === undefined) {
      return false
    }
    if (this === other) {
      return true
    }
    if (this.constructor !== other.constructor) {
      return false
    }
    return JSON.stringify(this.props) === JSON.stringify(other.props)
  }
}

