import type { DomainEvent } from './domain-event.js'

/** Identity contract entities are keyed by (value objects with equals). */
export interface EntityId {
  equals(other?: unknown): boolean
}

/**
 * Immutable entity base: identity plus the uncommitted domain events this
 * instance carries. State transitions on subclasses return NEW instances;
 * nothing here is ever mutated after construction.
 */
export abstract class Entity<TId extends EntityId> {
  readonly domainEvents: readonly DomainEvent[]

  protected constructor(
    readonly id: TId,
    domainEvents: readonly DomainEvent[] = []
  ) {
    this.domainEvents = Object.freeze([...domainEvents])
  }

  equals(other?: Entity<TId>): boolean {
    if (other === null || other === undefined) {
      return false
    }
    if (this === other) {
      return true
    }
    if (this.constructor !== other.constructor) {
      return false
    }
    return this.id.equals(other.id)
  }
}

