import type { DomainEvent } from './domain-event.js'
import type { EntityId } from './entity.js'
import { Entity } from './entity.js'

/**
 * Aggregate root: an entity with an optimistic-concurrency version.
 * Each state transition on a subclass returns a new instance with
 * version + 1 and the transition's event appended to domainEvents.
 */
export abstract class AggregateRoot<TId extends EntityId> extends Entity<TId> {
  protected constructor(
    id: TId,
    domainEvents: readonly DomainEvent[],
    readonly version: number
  ) {
    super(id, domainEvents)
  }
}

