import type { DomainEvent } from '../domain/domain-event.js'
import type { ILogger } from './logger.js'
import { NullLogger } from './logger.js'

export type EventHandler<T extends DomainEvent = DomainEvent> = (
  event: T
) => void | Promise<void>

export interface IEventBus {
  publish(event: DomainEvent): Promise<void>
  subscribe(eventName: string, handler: EventHandler): void
  unsubscribe(eventName: string, handler: EventHandler): void
}

/**
 * In-memory event bus. Handlers are isolated: one handler throwing does not
 * prevent the others from running; failures are logged, never propagated.
 */
export class InMemoryEventBus implements IEventBus {
  private readonly handlers = new Map<string, Set<EventHandler>>()

  constructor(private readonly logger: ILogger = new NullLogger()) {}

  subscribe(eventName: string, handler: EventHandler): void {
    const existing = this.handlers.get(eventName)
    if (existing) {
      existing.add(handler)
      return
    }
    this.handlers.set(eventName, new Set([handler]))
  }

  unsubscribe(eventName: string, handler: EventHandler): void {
    this.handlers.get(eventName)?.delete(handler)
  }

  async publish(event: DomainEvent): Promise<void> {
    const subscribers = this.handlers.get(event.eventName)
    if (!subscribers || subscribers.size === 0) {
      return
    }
    for (const handler of subscribers) {
      try {
        await handler(event)
      } catch (error) {
        this.logger.error(`Event handler failed for '${event.eventName}'`, {
          eventId: event.eventId,
          aggregateId: event.aggregateId,
          error: error instanceof Error ? error.message : String(error)
        })
      }
    }
  }
}

