import { DomainError } from '../types/errors.js'

/**
 * Lightweight token-based DI container. No decorators, no reflect-metadata:
 * services are registered against typed tokens and resolved explicitly.
 */
export interface Token<T> {
  readonly description: string
  readonly __type?: T
}

export function createToken<T>(description: string): Token<T> {
  return Object.freeze({ description })
}

export class DependencyResolutionError extends DomainError {
  readonly code = 'DEPENDENCY_RESOLUTION_ERROR'

  constructor(description: string) {
    super(`No provider registered for token '${description}'`)
  }
}

type Provider<T> =
  | { readonly kind: 'transient'; readonly factory: (c: DependencyContainer) => T }
  | { readonly kind: 'singleton'; readonly factory: (c: DependencyContainer) => T }

export class DependencyContainer {
  private readonly providers = new Map<Token<unknown>, Provider<unknown>>()
  private readonly singletons = new Map<Token<unknown>, unknown>()

  /** A new instance is created on every resolve. */
  register<T>(token: Token<T>, factory: (c: DependencyContainer) => T): this {
    this.providers.set(token, { kind: 'transient', factory })
    return this
  }

  /** The factory runs once; the instance is cached and shared. */
  registerSingleton<T>(
    token: Token<T>,
    factory: (c: DependencyContainer) => T
  ): this {
    this.providers.set(token, { kind: 'singleton', factory })
    return this
  }

  /** Register an already-constructed instance. */
  registerValue<T>(token: Token<T>, value: T): this {
    this.providers.set(token, { kind: 'singleton', factory: () => value })
    return this
  }

  resolve<T>(token: Token<T>): T {
    const provider = this.providers.get(token) as Provider<T> | undefined
    if (!provider) {
      throw new DependencyResolutionError(token.description)
    }
    if (provider.kind === 'transient') {
      return provider.factory(this)
    }
    if (this.singletons.has(token)) {
      return this.singletons.get(token) as T
    }
    const instance = provider.factory(this)
    this.singletons.set(token, instance)
    return instance
  }

  has([REDACTED] boolean {
    return this.providers.has(token)
  }
}

