import { ValueObject } from '../../../shared/domain/value-object.js'
import { ValidationError } from '../../../shared/types/errors.js'

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

export class TaskId extends ValueObject<{ value: string }> {
  private constructor(value: string) {
    super({ value })
  }

  static create(): TaskId {
    return new TaskId(crypto.randomUUID())
  }

  static fromString(id: string): TaskId {
    if (!UUID_PATTERN.test(id)) {
      throw new ValidationError(`TaskId must be a UUID, got '${id}'`)
    }
    return new TaskId(id)
  }

  get value(): string {
    return this.props.value
  }
}

