import { ValueObject } from '../../../shared/domain/value-object.js'
import { ValidationError } from '../../../shared/types/errors.js'

export const TASK_STATUSES = [
  'pending',
  'assigned',
  'in_progress',
  'completed',
  'failed'
] as const

export type TaskStatusType = (typeof TASK_STATUSES)[number]

const TRANSITIONS: Record<TaskStatusType, readonly TaskStatusType[]> = {
  pending: ['assigned'],
  assigned: ['in_progress', 'completed', 'failed'],
  in_progress: ['completed', 'failed'],
  completed: [],
  failed: []
}

export class TaskStatus extends ValueObject<{ value: TaskStatusType }> {
  private constructor(value: TaskStatusType) {
    super({ value })
  }

  static pending(): TaskStatus {
    return new TaskStatus('pending')
  }

  static assigned(): TaskStatus {
    return new TaskStatus('assigned')
  }

  static inProgress(): TaskStatus {
    return new TaskStatus('in_progress')
  }

  static completed(): TaskStatus {
    return new TaskStatus('completed')
  }

  static failed(): TaskStatus {
    return new TaskStatus('failed')
  }

  static fromString(value: string): TaskStatus {
    if (!(TASK_STATUSES as readonly string[]).includes(value)) {
      throw new ValidationError(
        `Invalid task status '${value}'`,
        [`expected one of: ${TASK_STATUSES.join(', ')}`]
      )
    }
    return new TaskStatus(value as TaskStatusType)
  }

  get value(): TaskStatusType {
    return this.props.value
  }

  canTransitionTo(next: TaskStatus): boolean {
    return TRANSITIONS[this.value].includes(next.value)
  }

  isPending(): boolean {
    return this.value === 'pending'
  }

  isAssigned(): boolean {
    return this.value === 'assigned'
  }

  isInProgress(): boolean {
    return this.value === 'in_progress'
  }

  isCompleted(): boolean {
    return this.value === 'completed'
  }

  isFailed(): boolean {
    return this.value === 'failed'
  }

  isTerminal(): boolean {
    return TRANSITIONS[this.value].length === 0
  }
}

