import { ValueObject } from '../../../shared/domain/value-object.js'
import { ValidationError } from '../../../shared/types/errors.js'

interface TaskResultProps extends Record<string, unknown> {
  success: boolean
  output: string | undefined
  errorMessage: string | undefined
}

export class TaskResult extends ValueObject<TaskResultProps> {
  private constructor(props: TaskResultProps) {
    super(props)
  }

  static success(output?: string): TaskResult {
    return new TaskResult({
      success: true,
      output: output ?? undefined,
      errorMessage: undefined
    })
  }

  static failure(errorMessage: string): TaskResult {
    if (errorMessage.trim().length === 0) {
      throw new ValidationError('TaskResult failure requires an error message')
    }
    return new TaskResult({
      success: false,
      output: undefined,
      errorMessage
    })
  }

  get isSuccess(): boolean {
    return this.props.success
  }

  get output(): string | undefined {
    return this.props.output
  }

  get errorMessage(): string | undefined {
    return this.props.errorMessage
  }
}

