import type { IClock } from '../../../shared/types/interfaces.js'
import type { Priority } from '../value-objects/priority.vo.js'

export class TaskAssignedEvent extends DomainEvent {
  static readonly EVENT_NAME = 'task.assigned'

  constructor(
    taskId: string,
    readonly agentId: string,
    readonly priority: Priority,
    clock?: IClock
  ) {
    super(TaskAssignedEvent.EVENT_NAME, taskId, clock)
    Object.freeze(this)
  }
}

