import type { Task } from '../entities/task.entity.js'
import type { PriorityLevel } from '../value-objects/priority.vo.js'

const BASE_DURATION_MS = 300_000 // 5 minutes

const PRIORITY_DURATION_MULTIPLIER: Record<PriorityLevel, number> = {
  low: 0.5,
  medium: 1.0,
  high: 1.5,
  critical: 2.0
}

/** Pure domain service: scheduling policy for tasks. Never mutates inputs. */
export class TaskSchedulingService {
  /** Highest priority first; FIFO (createdAt) within the same priority. */
  prioritizeTasks(tasks: readonly Task[]): readonly Task[] {
    return [...tasks].sort((a, b) => {
      const byPriority =
        b.priority.getNumericValue() - a.priority.getNumericValue()
      if (byPriority !== 0) {
        return byPriority
      }
      return a.createdAt.getTime() - b.createdAt.getTime()
    })
  }

  canSchedule(task: Task, agentCapacity: number): boolean {
    if (task.status.isTerminal()) {
      return false
    }
    // Critical tasks may exceed nominal capacity as long as any slot exists.
    if (task.priority.value === 'critical') {
      return true
    }
    return agentCapacity > 0
  }

  calculateEstimatedDuration(task: Task): number {
    return BASE_DURATION_MS * PRIORITY_DURATION_MULTIPLIER[task.priority.value]
  }
}

