import type { DatabaseSync } from 'node:sqlite'
import { z } from 'zod'

import { RepositoryError } from '../../../shared/types/errors.js'
import { Task } from '../entities/task.entity.js'
import { Priority, PRIORITY_LEVELS } from '../value-objects/priority.vo.js'
import { TaskId } from '../value-objects/task-id.vo.js'
import { TASK_STATUSES, TaskStatus } from '../value-objects/task-status.vo.js'
import type { ITaskRepository } from './task.repository.js'

/**
 * priority_rank is denormalized (Priority.getNumericValue) so ordering is
 * numeric — string ORDER BY priority would sort 'high' < 'low'.
 */
export function initTaskManagementSchema(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id TEXT PRIMARY KEY,
      description TEXT NOT NULL,
      priority TEXT NOT NULL,
      priority_rank INTEGER NOT NULL,
      status TEXT NOT NULL,
      assigned_agent_id TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      version INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status);
  `)
}

const taskRowSchema = z.object({
  id: z.string(),
  description: z.string(),
  priority: z.enum(PRIORITY_LEVELS),
  status: z.enum(TASK_STATUSES),
  assigned_agent_id: z.string().nullable(),
  created_at: z.string(),
  updated_at: z.string(),
  version: z.number().int().nonnegative()
})

export class SqliteTaskRepository implements ITaskRepository {
  constructor(private readonly db: DatabaseSync) {}

  async save(task: Task): Promise<void> {
    this.run(() => {
      const stmt = this.db.prepare(`
        INSERT OR REPLACE INTO tasks (
          id, description, priority, priority_rank, status,
          assigned_agent_id, created_at, updated_at, version
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `)
      stmt.run(
        task.id.value,
        task.description,
        task.priority.value,
        task.priority.getNumericValue(),
        task.status.value,
        task.assignedAgentId ?? null,
        task.createdAt.toISOString(),
        task.updatedAt.toISOString(),
        task.version
      )
    }, `Failed to save task ${task.id.value}`)
  }

  async findById(id: TaskId): Promise<Task | null> {
    return this.run(() => {
      const row = this.db
        .prepare('SELECT * FROM tasks WHERE id = ?')
        .get(id.value)
      return row === undefined ? null : this.mapRow(row)
    }, `Failed to load task ${id.value}`)
  }

  async findByAgentId(agentId: string): Promise<readonly Task[]> {
    return this.run(
      () =>
        this.db
          .prepare('SELECT * FROM tasks WHERE assigned_agent_id = ?')
          .all(agentId)
          .map((row) => this.mapRow(row)),
      `Failed to load tasks for agent ${agentId}`
    )
  }

  async findByStatus(status: TaskStatus): Promise<readonly Task[]> {
    return this.run(
      () =>
        this.db
          .prepare('SELECT * FROM tasks WHERE status = ?')
          .all(status.value)
          .map((row) => this.mapRow(row)),
      `Failed to load tasks with status ${status.value}`
    )
  }

  async findPendingTasks(): Promise<readonly Task[]> {
    return this.run(
      () =>
        this.db
          .prepare(
            `SELECT * FROM tasks WHERE status = 'pending'
             ORDER BY priority_rank DESC, created_at ASC`
          )
          .all()
          .map((row) => this.mapRow(row)),
      'Failed to load pending tasks'
    )
  }

  async delete(id: TaskId): Promise<void> {
    this.run(
      () => this.db.prepare('DELETE FROM tasks WHERE id = ?').run(id.value),
      `Failed to delete task ${id.value}`
    )
  }

  private mapRow(raw: unknown): Task {
    const parsed = taskRowSchema.safeParse(raw)
    if (!parsed.success) {
      throw new RepositoryError(
        'Corrupt task row in database',
        parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`)
      )
    }
    const row = parsed.data
    return Task.reconstitute(
      {
        id: TaskId.fromString(row.id),
        description: row.description,
        priority: Priority.fromString(row.priority),
        status: TaskStatus.fromString(row.status),
        assignedAgentId: row.assigned_agent_id ?? undefined,
        createdAt: new Date(row.created_at),
        updatedAt: new Date(row.updated_at)
      },
      row.version
    )
  }

  /** Wrap driver failures in RepositoryError; never leak raw driver errors. */
  private run<T>(fn: () => T, message: string): T {
    try {
      return fn()
    } catch (error) {
      if (error instanceof RepositoryError) {
        throw error
      }
      throw new RepositoryError(message, error)
    }
  }
}

