  private mapRow(raw: unknown): Task {
    const parsed = taskRowSchema.safeParse(raw)
    if (!parsed.success) {
      throw new RepositoryError(
        'Corrupt task row in database',
        parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`)
      )
    }
    const row = parsed.data
    return Task.reconstitute(
      {
        id: TaskId.fromString(row.id),
        description: row.description,
        priority: Priority.fromString(row.priority),
        status: TaskStatus.fromString(row.status),
        assignedAgentId: row.assigned_agent_id ?? undefined,
        createdAt: new Date(row.created_at),
        updatedAt: new Date(row.updated_at)
      },
      row.version
    )
  }

  /** Wrap driver failures in RepositoryError; never leak raw driver errors. */
  private run<T>(fn: () => T, message: string): T {
    try {
      return fn()
    } catch (error) {
      if (error instanceof RepositoryError) {
        throw error
      }
      throw new RepositoryError(message, error)
    }
  }
}
