import { z } from 'zod'

import { ValidationError } from '../../shared/types/errors.js'

const assignTaskCommandSchema = z.object({
  taskId: z.uuid(),
  agentId: z.string().trim().min(1)
})

export type AssignTaskCommand = z.infer<typeof assignTaskCommandSchema>

/** Boundary validation: unknown input in, typed command out (or throws). */
export function parseAssignTaskCommand(input: unknown): AssignTaskCommand {
  const parsed = assignTaskCommandSchema.safeParse(input)
  if (!parsed.success) {
    throw new ValidationError(
      'Invalid AssignTask command',
      parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`)
    )
  }
  return parsed.data
}

import type {
  DomainError,
  InvalidTaskStateTransitionError,
  NotFoundError,
  RepositoryError,
  UnexpectedError,
  ValidationError
} from '../../shared/types/errors.js'

export interface AssignTaskSuccess {
  readonly taskId: string
  readonly agentId: string
  readonly assignedAt: Date
}

export class AgentUnavailableError extends Error {
  readonly code = 'AGENT_UNAVAILABLE'

  constructor(readonly agentId: string) {
    super(`Agent is not available: ${agentId}`)
    this.name = 'AgentUnavailableError'
  }
}

export type AssignTaskError =
  | ValidationError
  | NotFoundError
  | AgentUnavailableError
  | InvalidTaskStateTransitionError
  | RepositoryError
  | UnexpectedError
  | DomainError

