import type { ITaskRepository } from '../../domains/task-management/repositories/task.repository.js'
import { TaskId } from '../../domains/task-management/value-objects/task-id.vo.js'
import type { IEventBus } from '../../shared/infrastructure/event-bus.js'
import type { ILogger } from '../../shared/infrastructure/logger.js'
import type { Result } from '../../shared/types/common.js'
import { err, ok } from '../../shared/types/common.js'
import { DomainError, NotFoundError, UnexpectedError } from '../../shared/types/errors.js'
import type { IClock, IUseCase } from '../../shared/types/interfaces.js'
import { SystemClock } from '../../shared/types/interfaces.js'
import { parseAssignTaskCommand } from '../commands/assign-task.command.js'
import type { IAgentAvailability } from '../ports/agent-availability.port.js'
import type {
  AssignTaskError,
  AssignTaskSuccess
} from '../results/assign-task.result.js'
import { AgentUnavailableError } from '../results/assign-task.result.js'

export class AssignTaskUseCase
  implements IUseCase<unknown, Result<AssignTaskSuccess, AssignTaskError>>
{
  constructor(
    private readonly taskRepository: ITaskRepository,
    private readonly agentAvailability: IAgentAvailability,
    private readonly eventBus: IEventBus,
    private readonly logger: ILogger,
    private readonly clock: IClock = new SystemClock()
  ) {}

  async execute(
    input: unknown
  ): Promise<Result<AssignTaskSuccess, AssignTaskError>> {
    try {
      const command = parseAssignTaskCommand(input)
      const taskId = TaskId.fromString(command.taskId)

      const task = await this.taskRepository.findById(taskId)
      if (task === null) {
        return err(new NotFoundError('Task', command.taskId))
      }

      const available = await this.agentAvailability.isAvailable(
        command.agentId
      )
      if (!available) {
        return err(new AgentUnavailableError(command.agentId))
      }

      const assigned = task.assignTo(command.agentId, this.clock)

      await this.taskRepository.save(assigned)

      // Publish only after a successful persist. Delivery is at-least-once:
      // a crash between save and publish drops the events.
      for (const event of assigned.domainEvents) {
        await this.eventBus.publish(event)
      }

      this.logger.info('Task assigned', {
        taskId: assigned.id.value,
        agentId: command.agentId
      })

      return ok({
        taskId: assigned.id.value,
        agentId: command.agentId,
        assignedAt: assigned.updatedAt
      })
    } catch (error) {
      if (error instanceof DomainError) {
        return err(error)
      }
      this.logger.error('AssignTask failed unexpectedly', {
        error: error instanceof Error ? error.message : String(error)
      })
      return err(UnexpectedError.from(error))
    }
  }
}

