/**
 * Typed error hierarchy for the core. Every error crossing a layer boundary
 * is one of these; raw/unknown errors are wrapped in UnexpectedError so
 * internals are never leaked to callers.
 */
export abstract class DomainError extends Error {
  abstract readonly code: string

  constructor(message: string) {
    super(message)
    this.name = new.target.name
  }
}

export class ValidationError extends DomainError {
  readonly code = 'VALIDATION_ERROR'

  constructor(
    message: string,
    readonly details: readonly string[] = []
  ) {
    super(message)
  }
}

export class NotFoundError extends DomainError {
  readonly code = 'NOT_FOUND'

  constructor(
    readonly resource: string,
    readonly resourceId: string
  ) {
    super(`${resource} not found: ${resourceId}`)
  }
}

export class InvalidTaskStateTransitionError extends DomainError {
  readonly code = 'INVALID_TASK_STATE_TRANSITION'

  constructor(
    readonly from: string,
    readonly attempted: string
  ) {
    super(`Cannot transition task from '${from}' via '${attempted}'`)
