import type { Task } from '../../src/core/domains/task-management/entities/task.entity.js'
import type { ITaskRepository } from '../../src/core/domains/task-management/repositories/task.repository.js'
import type { TaskId } from '../../src/core/domains/task-management/value-objects/task-id.vo.js'
import type { TaskStatus } from '../../src/core/domains/task-management/value-objects/task-status.vo.js'
import type { IAgentAvailability } from '../../src/core/application/ports/agent-availability.port.js'
import type { DomainEvent } from '../../src/core/shared/domain/domain-event.js'
import type {
  EventHandler,
  IEventBus
} from '../../src/core/shared/infrastructure/event-bus.js'
import type { IClock } from '../../src/core/shared/types/interfaces.js'

export class InMemoryTaskRepository implements ITaskRepository {
  private readonly tasks = new Map<string, Task>()
  failNextSave: Error | null = null

  async save(task: Task): Promise<void> {
    if (this.failNextSave) {
      const error = this.failNextSave
      this.failNextSave = null
      throw error
    }
    this.tasks.set(task.id.value, task.clearDomainEvents())
  }

  async findById(id: TaskId): Promise<Task | null> {
    return this.tasks.get(id.value) ?? null
  }

  async findByAgentId(agentId: string): Promise<readonly Task[]> {
    return [...this.tasks.values()].filter(
      (t) => t.assignedAgentId === agentId
    )
  }

  async findByStatus(status: TaskStatus): Promise<readonly Task[]> {
    return [...this.tasks.values()].filter((t) => t.status.equals(status))
  }

  async findPendingTasks(): Promise<readonly Task[]> {
    return [...this.tasks.values()].filter((t) => t.status.isPending())
  }

  async delete(id: TaskId): Promise<void> {
    this.tasks.delete(id.value)
  }
}

export class StubAgentAvailability implements IAgentAvailability {
  constructor(private readonly available: boolean = true) {}

  async isAvailable(): Promise<boolean> {
    return this.available
  }
}

export class RecordingEventBus implements IEventBus {
  readonly published: DomainEvent[] = []

  async publish(event: DomainEvent): Promise<void> {
    this.published.push(event)
  }

  subscribe(_eventName: string, _handler: EventHandler): void {}
  unsubscribe(_eventName: string, _handler: EventHandler): void {}
}

export class FixedClock implements IClock {
  constructor(private readonly fixed: Date) {}

  now(): Date {
    return new Date(this.fixed)
  }
}

import { Task } from '../../src/core/domains/task-management/entities/task.entity.js'
import { Priority } from '../../src/core/domains/task-management/value-objects/priority.vo.js'
import type { IClock } from '../../src/core/shared/types/interfaces.js'
import { FixedClock } from './fakes.js'

export const TEST_EPOCH = new Date('2026-01-01T00:00:00.000Z')

export function aTask(
  overrides: {
    description?: string
    priority?: Priority
    clock?: IClock
  } = {}
): Task {
  return Task.create(
    overrides.description ?? 'Test task',
    overrides.priority ?? Priority.medium(),
    overrides.clock ?? new FixedClock(TEST_EPOCH)
  )
}

