input.content:
import { describe, expect, it } from 'vitest'

import { ValueObject } from '../../../src/core/shared/domain/value-object.js'

class Money extends ValueObject<{ amount: number; currency: string }> {
  constructor(amount: number, currency: string) {
    super({ amount, currency })
  }

  get amount(): number {
    return this.props.amount
  }
}

class OtherMoney extends ValueObject<{ amount: number; currency: string }> {
  constructor(amount: number, currency: string) {
    super({ amount, currency })
  }
}

describe('ValueObject', () => {
  it('freezes its props', () => {
    const money = new Money(10, 'USD')
    expect(Object.isFrozen(money['props'])).toBe(true)
  })

  it('is equal to another instance with the same props', () => {
    expect(new Money(10, 'USD').equals(new Money(10, 'USD'))).toBe(true)
  })

  it('is not equal when props differ', () => {
    expect(new Money(10, 'USD').equals(new Money(11, 'USD'))).toBe(false)
    expect(new Money(10, 'USD').equals(new Money(10, 'EUR'))).toBe(false)
  })

  it('is not equal to a different class with the same props', () => {
    const a = new Money(10, 'USD')
    const b = new OtherMoney(10, 'USD')
    expect(a.equals(b as unknown as Money)).toBe(false)
  })

  it('is not equal to undefined', () => {
    expect(new Money(10, 'USD').equals(undefined)).toBe(false)
  })

  it('is equal to itself', () => {
    const money = new Money(10, 'USD')
    expect(money.equals(money)).toBe(true)
  })
})

