import { afterEach, describe, expect, it, vi } from 'vitest'

import {
  ConsoleLogger,
  NullLogger
} from '../../../src/core/shared/infrastructure/logger.js'

describe('ConsoleLogger', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('writes messages at or above the minimum level', () => {
    const info = vi.spyOn(console, 'info').mockImplementation(() => {})
    const debug = vi.spyOn(console, 'debug').mockImplementation(() => {})
    const logger = new ConsoleLogger('info')

    logger.debug('too low')
    logger.info('visible')

    expect(debug).not.toHaveBeenCalled()
    expect(info).toHaveBeenCalledTimes(1)
    expect(String(info.mock.calls[0]?.[0])).toContain('visible')
  })

  it('passes context through when provided', () => {
    const error = vi.spyOn(console, 'error').mockImplementation(() => {})
    const logger = new ConsoleLogger('error')

    logger.error('failed', { taskId: 't1' })

    expect(error).toHaveBeenCalledWith(
      expect.stringContaining('[ERROR] failed'),
      { taskId: 't1' }
    )
  })

  it('emits warn level via console.warn', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    new ConsoleLogger('debug').warn('careful')
    expect(warn).toHaveBeenCalledTimes(1)
  })
})

describe('NullLogger', () => {
  it('swallows everything silently', () => {
    const logger = new NullLogger()
    expect(() => {
      logger.debug('a')
      logger.info('b')
      logger.warn('c')
      logger.error('d')
    }).not.toThrow()
  })
})

