import { describe, expect, it } from 'vitest'

import { Task } from '../../../src/core/domains/task-management/entities/task.entity.js'
import { TaskAssignedEvent } from '../../../src/core/domains/task-management/events/task-assigned.event.js'
import { TaskCompletedEvent } from '../../../src/core/domains/task-management/events/task-completed.event.js'
import { Priority } from '../../../src/core/domains/task-management/value-objects/priority.vo.js'
import { TaskResult } from '../../../src/core/domains/task-management/value-objects/task-result.vo.js'
import {
  InvalidTaskStateTransitionError,
  ValidationError
} from '../../../src/core/shared/types/errors.js'
import { aTask, TEST_EPOCH } from '../../helpers/builders.js'
import { FixedClock } from '../../helpers/fakes.js'

describe('Task.create', () => {
  it('creates a pending task with version 0 and no events', () => {
    const task = aTask({ description: 'Ship it', priority: Priority.high() })

    expect(task.description).toBe('Ship it')
    expect(task.priority.equals(Priority.high())).toBe(true)
    expect(task.status.isPending()).toBe(true)
    expect(task.assignedAgentId).toBeUndefined()
    expect(task.version).toBe(0)
    expect(task.domainEvents).toHaveLength(0)
    expect(task.createdAt).toEqual(TEST_EPOCH)
  })

  it('generates unique ids', () => {
    expect(aTask().id.equals(aTask().id)).toBe(false)
  })

  it('rejects empty descriptions', () => {
    expect(() => aTask({ description: '   ' })).toThrow(ValidationError)
  })
})

describe('Task.assignTo', () => {
  it('returns a NEW assigned instance and leaves the original untouched', () => {
    const task = aTask()
    const assigned = task.assignTo('agent-123')

    expect(assigned).not.toBe(task)
    expect(assigned.status.isAssigned()).toBe(true)
    expect(assigned.assignedAgentId).toBe('agent-123')
    expect(assigned.version).toBe(1)

    // original unchanged
    expect(task.status.isPending()).toBe(true)
    expect(task.assignedAgentId).toBeUndefined()
    expect(task.version).toBe(0)
    expect(task.domainEvents).toHaveLength(0)
  })

  it('emits a TaskAssignedEvent', () => {
    const assigned = aTask().assignTo('agent-123')

    expect(assigned.domainEvents).toHaveLength(1)
    const event = assigned.domainEvents[0]
    expect(event).toBeInstanceOf(TaskAssignedEvent)
    expect((event as TaskAssignedEvent).agentId).toBe('agent-123')
    expect(event?.aggregateId).toBe(assigned.id.value)
  })

  it('rejects empty agent ids', () => {
    expect(() => aTask().assignTo('  ')).toThrow(ValidationError)
  })

  it('rejects assignment of a completed task', () => {
    const done = aTask()
      .assignTo('agent-1')
      .complete(TaskResult.success('ok'))

    expect(() => done.assignTo('agent-2')).toThrow(
      InvalidTaskStateTransitionError
    )
  })

  it('rejects assignment of an already-assigned task', () => {
    const assigned = aTask().assignTo('agent-1')
    expect(() => assigned.assignTo('agent-2')).toThrow(
      InvalidTaskStateTransitionError
    )
  })
})

describe('Task.complete', () => {
  it('completes an assigned task and computes duration', () => {
    const later = new FixedClock(new Date(TEST_EPOCH.getTime() + 60_000))
    const completed = aTask()
      .assignTo('agent-1')
      .complete(TaskResult.success('ok'), later)

    expect(completed.status.isCompleted()).toBe(true)
    expect(completed.version).toBe(2)
    const event = completed.domainEvents[1]
    expect(event).toBeInstanceOf(TaskCompletedEvent)
    expect((event as TaskCompletedEvent).durationMs).toBe(60_000)
  })

  it('marks the task failed when the result is a failure', () => {
    const failed = aTask()
      .assignTo('agent-1')
      .complete(TaskResult.failure('crash'))

    expect(failed.status.isFailed()).toBe(true)
  })

  it('accumulates events across transitions', () => {
    const completed = aTask()
      .assignTo('agent-1')
      .complete(TaskResult.success())

    expect(completed.domainEvents).toHaveLength(2)
    expect(completed.domainEvents[0]).toBeInstanceOf(TaskAssignedEvent)
    expect(completed.domainEvents[1]).toBeInstanceOf(TaskCompletedEvent)
  })

  it('rejects completing an unassigned task', () => {
    expect(() => aTask().complete(TaskResult.success())).toThrow(
      InvalidTaskStateTransitionError
    )
  })
})

describe('Task.clearDomainEvents', () => {
  it('returns a copy with the same state but no events', () => {
    const assigned = aTask().assignTo('agent-1')
    const clean = assigned.clearDomainEvents()

    expect(clean).not.toBe(assigned)
    expect(clean.domainEvents).toHaveLength(0)
    expect(clean.version).toBe(assigned.version)
    expect(clean.status.equals(assigned.status)).toBe(true)
    expect(assigned.domainEvents).toHaveLength(1)
  })
})

describe('Task.reconstitute', () => {
  it('rebuilds from persistence with no uncommitted events', () => {
    const source = aTask().assignTo('agent-1')
    const rebuilt = Task.reconstitute(
      {
        id: source.id,
        description: source.description,
        priority: source.priority,
        status: source.status,
        assignedAgentId: source.assignedAgentId,
        createdAt: source.createdAt,
        updatedAt: source.updatedAt
      },
      source.version
    )

    expect(rebuilt.equals(source)).toBe(true)
    expect(rebuilt.domainEvents).toHaveLength(0)
    expect(rebuilt.version).toBe(1)
  })
})

describe('Task immutability', () => {
  it('freezes exposed structures', () => {
    const task = aTask()
    expect(Object.isFrozen(task.domainEvents)).toBe(true)
    expect(Object.isFrozen(task['props'])).toBe(true)
  })
})

