import { describe, expect, it } from 'vitest'

import { TaskSchedulingService } from '../../../src/core/domains/task-management/services/task-scheduling.service.js'
import { Priority } from '../../../src/core/domains/task-management/value-objects/priority.vo.js'
import { TaskResult } from '../../../src/core/domains/task-management/value-objects/task-result.vo.js'
import { aTask } from '../../helpers/builders.js'
import { FixedClock } from '../../helpers/fakes.js'

const service = new TaskSchedulingService()

describe('prioritizeTasks', () => {
  it('sorts highest priority first', () => {
    const low = aTask({ priority: Priority.low() })
    const critical = aTask({ priority: Priority.critical() })
    const medium = aTask({ priority: Priority.medium() })

    const sorted = service.prioritizeTasks([low, critical, medium])

    expect(sorted.map((t) => t.priority.value)).toEqual([
      'critical',
      'medium',
      'low'
    ])
  })

  it('breaks priority ties by creation time (FIFO)', () => {
    const earlier = aTask({
      clock: new FixedClock(new Date('2026-01-01T00:00:00Z'))
    })
    const later = aTask({
      clock: new FixedClock(new Date('2026-01-02T00:00:00Z'))
    })

    const sorted = service.prioritizeTasks([later, earlier])

    expect(sorted[0]?.id.equals(earlier.id)).toBe(true)
  })

  it('does not mutate the input array', () => {
    const low = aTask({ priority: Priority.low() })
    const high = aTask({ priority: Priority.high() })
    const input = [low, high]

    service.prioritizeTasks(input)

    expect(input[0]).toBe(low)
    expect(input[1]).toBe(high)
  })
})

describe('canSchedule', () => {
  it('allows critical tasks regardless of nominal capacity', () => {
    const critical = aTask({ priority: Priority.critical() })
    expect(service.canSchedule(critical, 0)).toBe(true)
  })

  it('requires capacity for non-critical tasks', () => {
    const medium = aTask({ priority: Priority.medium() })
    expect(service.canSchedule(medium, 0)).toBe(false)
    expect(service.canSchedule(medium, 1)).toBe(true)
  })

  it('never schedules terminal tasks', () => {
    const done = aTask({ priority: Priority.critical() })
      .assignTo('agent-1')
      .complete(TaskResult.success())
    expect(service.canSchedule(done, 5)).toBe(false)
  })
})

describe('calculateEstimatedDuration', () => {
  it('scales the base duration by priority', () => {
    expect(
      service.calculateEstimatedDuration(aTask({ priority: Priority.low() }))
    ).toBe(150_000)
    expect(
      service.calculateEstimatedDuration(aTask({ priority: Priority.medium() }))
    ).toBe(300_000)
    expect(
      service.calculateEstimatedDuration(
        aTask({ priority: Priority.critical() })
      )
    ).toBe(600_000)
  })
})

