import { NullLogger } from '../../../src/core/shared/infrastructure/logger.js'
import {
  InvalidTaskStateTransitionError,
  NotFoundError,
  UnexpectedError,
  ValidationError
} from '../../../src/core/shared/types/errors.js'
import { aTask, TEST_EPOCH } from '../../helpers/builders.js'
import {
  FixedClock,
  InMemoryTaskRepository,
  RecordingEventBus,
  StubAgentAvailability
} from '../../helpers/fakes.js'

describe('AssignTaskUseCase', () => {
  let repo: InMemoryTaskRepository
  let bus: RecordingEventBus

  beforeEach(() => {
    repo = new InMemoryTaskRepository()
    bus = new RecordingEventBus()
  })

  function useCase(available = true): AssignTaskUseCase {
    return new AssignTaskUseCase(
      repo,
      new StubAgentAvailability(available),
      bus,
      new NullLogger(),
      new FixedClock(TEST_EPOCH)
    )
  }

  it('assigns a pending task, persists it, and publishes events', async () => {
    const task = aTask()
    await repo.save(task)

    const result = await useCase().execute({
      taskId: task.id.value,
      agentId: 'agent-7'
    })

    expect(result.ok).toBe(true)
    if (result.ok) {
      expect(result.value.taskId).toBe(task.id.value)
      expect(result.value.agentId).toBe('agent-7')
      expect(result.value.assignedAt).toEqual(TEST_EPOCH)
    }

    const persisted = await repo.findById(task.id)
    expect(persisted?.status.isAssigned()).toBe(true)
    expect(persisted?.assignedAgentId).toBe('agent-7')
    expect(persisted?.version).toBe(1)

    expect(bus.published).toHaveLength(1)
    expect(bus.published[0]).toBeInstanceOf(TaskAssignedEvent)
  })

  it('returns ValidationError for malformed input without throwing', async () => {
    const result = await useCase().execute({ taskId: 'nope', agentId: '' })

    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toBeInstanceOf(ValidationError)
    }
    expect(bus.published).toHaveLength(0)
  })

  it('returns NotFoundError when the task does not exist', async () => {
    const result = await useCase().execute({
      taskId: crypto.randomUUID(),
      agentId: 'agent-7'
    })

    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toBeInstanceOf(NotFoundError)
    }
  })

  it('returns AgentUnavailableError when the agent cannot take work', async () => {
    const task = aTask()
    await repo.save(task)

    const result = await useCase(false).execute({
      taskId: task.id.value,
      agentId: 'agent-7'
    })

    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toBeInstanceOf(AgentUnavailableError)
    }
    const untouched = await repo.findById(task.id)
    expect(untouched?.status.isPending()).toBe(true)
  })

  it('maps illegal state transitions to a typed error', async () => {
    const completed = aTask()
      .assignTo('agent-1')
      .complete(TaskResult.success())
    await repo.save(completed)

    const result = await useCase().execute({
      taskId: completed.id.value,
      agentId: 'agent-2'
    })

    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toBeInstanceOf(InvalidTaskStateTransitionError)
    }
    expect(bus.published).toHaveLength(0)
  })

  it('wraps unknown repository failures and publishes nothing', async () => {
    const task = aTask()
    await repo.save(task)
    repo.failNextSave = new Error('disk on fire')

    const result = await useCase().execute({
      taskId: task.id.value,
      agentId: 'agent-7'
    })

    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toBeInstanceOf(UnexpectedError)
    }
    expect(bus.published).toHaveLength(0)
  })
})
