import { DatabaseSync } from 'node:sqlite'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'

import {
  initTaskManagementSchema,
  SqliteTaskRepository
} from '../../src/core/domains/task-management/repositories/sqlite-task.repository.js'
import { Priority } from '../../src/core/domains/task-management/value-objects/priority.vo.js'
import { TaskId } from '../../src/core/domains/task-management/value-objects/task-id.vo.js'
import { TaskStatus } from '../../src/core/domains/task-management/value-objects/task-status.vo.js'
import { RepositoryError } from '../../src/core/shared/types/errors.js'
import { aTask } from '../helpers/builders.js'
import { FixedClock } from '../helpers/fakes.js'

describe('SqliteTaskRepository (integration)', () => {
  let db: DatabaseSync
  let repo: SqliteTaskRepository

  beforeEach(() => {
    db = new DatabaseSync(':memory:')
    initTaskManagementSchema(db)
    repo = new SqliteTaskRepository(db)
  })

  afterEach(() => {
    db.close()
  })

  it('round-trips a task through save and findById', async () => {
    const task = aTask({ description: 'Round trip', priority: Priority.high() })
    await repo.save(task)

    const loaded = await repo.findById(task.id)

    expect(loaded).not.toBeNull()
    expect(loaded?.id.equals(task.id)).toBe(true)
    expect(loaded?.description).toBe('Round trip')
    expect(loaded?.priority.equals(Priority.high())).toBe(true)
